import React, { useEffect, useState } from "react";
import "./../css/bot.css";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
import TimePicker from "react-time-picker";
import BarChart from "./BloodAvailability";
import Bot from "./Bot";

function Home() {
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [selectedService, setSelectedService] = useState(null);
  const [userLocation, setUserLocation] = useState(null);
  const [searchResultsTable, setSearchResultsTable] = useState([]);

  const handleInputChange = (e) => {
    const searchTerm = e.target.value;
    setSearchTerm(searchTerm);

    if (searchTerm.trim() === "") {
      setSearchResults([]);
    } else {
      const results = services
        .filter((service) =>
          service.hsServices.toLowerCase().includes(searchTerm.toLowerCase())
        )
        .reduce((uniqueResults, service) => {
          // Check if the service is already in uniqueResults
          if (
            !uniqueResults.some(
              (result) => result.hsServices === service.hsServices
            )
          ) {
            // If not, add it to uniqueResults
            uniqueResults.push(service);
          }
          return uniqueResults;
        }, []);

      setSearchResults(results);
    }
  };

  const handleServiceSelect = (selectedService) => {
    setSelectedService(selectedService);
    setSearchTerm(selectedService.hsServices); // Populate search bar
    setSearchResults([]); // Clear search results
  };

  const handleSearch = async () => {
    if (selectedService && userLocation) {
      try {
        // Reset previous info apart from user latitude and longitude
        setSelectedService(null);
        setSearchResults([]);
        setSearchResultsTable([]);

        const response = await fetch(
          "http://localhost:5206/api/HospitalServices/Search",
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              userLatitude: userLocation.latitude,
              userLongitude: userLocation.longitude,
              service: selectedService.hsServices,
            }),
          }
        );

        if (response.ok) {
          const data = await response.json();
          // Handle the response data as needed
          console.log("Nearest Hospital:", data);
          setSearchResultsTable(data);
        } else {
          console.error("Error fetching nearest hospital from API");
          // Show an error message
          setSearchResultsTable([]);
          setSearchResults([{ hsServices: "Error fetching data" }]);
        }
      } catch (error) {
        console.error("Error:", error);
      }
    }
  };

  const SearchResultList = ({ results }) => (
    <ul className="list-group list-group-flush">
      {results.map((service, index) => (
        <li
          className="list-group-item"
          key={index}
          onClick={() => handleServiceSelect(service)}
        >
          {service.hsServices}
        </li>
      ))}
    </ul>
  );

  //call services api

  const [services, setServices] = useState([]);

  useEffect(() => {
    const fetchServices = async () => {
      try {
        const response = await fetch(
          "http://localhost:5206/api/HospitalServices"
        );

        if (response.ok) {
          const data = await response.json();
          setServices(data); // Assuming the API response is an array of services
        } else {
          console.error("Error fetching services from API");
        }
      } catch (error) {
        console.error("Error:", error);
      }
    };

    fetchServices();
  }, []);

  const SearchResultsTable = ({ results }) => (
    <div className="row mt-3">
      {results.map((result, index) => (
        <div key={index} className="col-lg-6 col-md-6">
          <div className="service-item bg-light rounded d-flex flex-column align-items-center justify-content-center text-center">
            <div className="service-icon mb-4">
              <i className="fa fa-2x fa-user-md text-white" />
            </div>
            <h3 className="mb-3">{result.hName}</h3>
            <h5 className="m-0">{result.hAddress}</h5>
            <br />
            <h4 className="m-0" style={{ color: "red" }}>
              Distance: {result.distanceInKm.toFixed(2)} km
            </h4>
          </div>
        </div>
      ))}
    </div>
  );
  /// end services api

  useEffect(() => {
    const fetchLocation = async () => {
      try {
        const position = await getCurrentLocation();
        setUserLocation(position.coords);
      } catch (error) {
        console.error("Error getting user location:", error);
      }
    };

    fetchLocation();
  }, []);

  const getCurrentLocation = () => {
    return new Promise((resolve, reject) => {
      if ("geolocation" in navigator) {
        navigator.geolocation.getCurrentPosition(resolve, reject);
      } else {
        reject("Geolocation not available");
      }
    });
  };

  const [doctors, setDoctors] = useState([]);

  useEffect(() => {
    const fetchDoctors = async () => {
      try {
        const response = await fetch("http://localhost:5206/api/Doctors_Cr");

        if (response.ok) {
          const data = await response.json();
          setDoctors(data);
        } else {
          console.error("Error fetching doctors from API");
        }
      } catch (error) {
        console.error("Error:", error);
      }
    };

    fetchDoctors();
  }, []);

  const getOneDoctorPerHospital = () => {
    const uniqueHospitals = new Set();
    const doctorsPerHospital = [];

    doctors.forEach((doctor) => {
      if (!uniqueHospitals.has(doctor.dhId)) {
        uniqueHospitals.add(doctor.dhId);
        doctorsPerHospital.push(doctor);
      }
    });

    return doctorsPerHospital;
  };

  const doctorsList = getOneDoctorPerHospital();

  //doctors appointment

  const [dobPickerOpen, setDobPickerOpen] = useState(false);
  const [apptDatePickerOpen, setApptDatePickerOpen] = useState(false);

  const handleDOBChange = (date) => {
    setFormData((prevFormData) => ({ ...prevFormData, APatientDOB: date }));
    setDobPickerOpen(false);
  };

  const handleApptDateChange = (date) => {
    setFormData((prevFormData) => ({ ...prevFormData, ADate: date }));
    setApptDatePickerOpen(false);
  };

  const [formData, setFormData] = useState({
    APatientName: "",
    APatientDOB: "",
    ADate: "",
    ATime: "",
    ADId: "",
    AType: "",
    AMobile: "",
    AEmail: "",
    AReason: "",
  });

  const [doctorsA, setDoctorsA] = useState([]);
  const [hospitals, setHospitals] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchDoctorsA = async (dhId) => {
    try {
      const response = await fetch(
        `http://localhost:5206/api/Doctors_Cr/ByHospitalId/${dhId}`
      );
      if (response.ok) {
        const doctorList = await response.json();
        setDoctorsA(doctorList); // Update the doctorsA state
      } else {
        console.error(
          "Failed to fetch doctors:",
          response.status,
          response.statusText
        );
      }
    } catch (error) {
      console.error("An error occurred while fetching doctors:", error);
    }
  };



  useEffect(() => {
    const fetchHospitalsA = async () => {
      try {
        const response = await fetch("http://localhost:5206/api/Hospital_Cr");
        if (response.ok) {
          const hospitalList = await response.json();
          setHospitals(hospitalList);
          if (hospitalList.length > 0) {
            await fetchDoctorsA(hospitalList[0].hId); // Fetch doctors for the first hospital by default
          }
        } else {
          console.error(
            "Failed to fetch hospitals:",
            response.status,
            response.statusText
          );
        }
      } catch (error) {
        console.error("An error occurred while fetching hospitals:", error);
      }
    };

    fetchHospitalsA();
  }, []);


  const handleSubmitA = async (e) => {
    e.preventDefault();
    console.log("Form submitted");

    try {
      setLoading(true);
      console.log("Form Data:", formData); // Log the form data for debugging

      // Make sure to format the date and time before sending to the server
      const formattedData = {
        ...formData,
        APatientDOB: formatDate(formData.APatientDOB),
        ADate: formatDate(formData.ADate),
        ATime: formatTime(formData.ATime),
      };

      const response = await fetch("http://localhost:5206/api/appointment_cr", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formattedData),
      });

      if (response.ok) {
        setFormData({
          APatientName: "",
          APatientDOB: "",
          ADate: "",
          ATime: "",
          ADId: "",
          AType: "",
          AMobile: "",
          AEmail: "",
          AReason: "",
        });
        setLoading(false);
        // Add any additional actions you want to perform after successful submission
      } else {
        console.error(
          "Failed to create appointment:",
          response.status,
          response.statusText
        );
      }
    } catch (error) {
      console.error("An error occurred during form submission:", error);
      setLoading(false);
    }
  };

  const handleInputChangeA = async (e) => {
    const { name, value } = e.target;

    // Convert date and time values to the desired format
    const formattedValue =
      name === "APatientDOB" || name === "ADate" ? formatDate(value) : value;

    setFormData((prevFormData) => ({
      ...prevFormData,
      [name]: formattedValue,
    }));

    if (name === "ADhId") {
      setDoctorsA([]); // Clear the existing doctorsA list
      if (value) {
        await fetchDoctorsA(value); // Fetch doctors for the selected hospital
      }
    }
  };


  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toISOString().split("T")[0]; // Format as 'yyyy-mm-dd'
  };

  const formatTime = (timeString) => {
    return `${timeString}:00.0000000`;
  };

  /// appountment end

  return (
    <div>
      <div>



        <div className="container-fluid bg-primary my-3 py-5">
          <div className="container py-5">
            <div className="row gx-5">
              <div className="col-lg-6 mb-5 mb-lg-0">
                <div className="mb-4">
                  <h5 className="d-inline-block text-white text-uppercase border-bottom border-5">
                    Appointment
                  </h5>
                  <h1 className="display-4">Make An Appointment</h1>
                </div>
                <p className="text-white mb-5">
                  Make an appointment with the hospital of your choice in your
                  comfortable time
                </p>
              </div>

              <div className="col-lg-6">
                <div className="bg-white text-center rounded p-5">
                  <h1 className="mb-4">Book An Appointment</h1>
                  <form onSubmit={handleSubmitA}>
                    <div className="row g-3">
                      <div className="col-12">
                        <input
                          type="text"
                          required
                          className="form-control bg-light border-0"
                          placeholder="Your Name"
                          style={{ height: 55 }}
                          name="APatientName"
                          value={formData.APatientName}
                          onChange={handleInputChangeA}
                        />
                      </div>
                      <div className="col-12">
                        <DatePicker
                          selected={formData.APatientDOB}
                          className="form-control bg-light border-0"
                          onChange={handleDOBChange}
                          placeholderText="Date Of Birth (mm/dd/yyyy)"
                          dateFormat="MM/dd/yyyy"
                          peekNextMonth
                          showMonthDropdown
                          showYearDropdown
                          required
                          dropdownMode="select"
                          maxDate={new Date()}
                        />
                      </div>
                      <div className="col-12">
                        <DatePicker
                          selected={formData.ADate}
                          onChange={handleApptDateChange}
                          className="form-control bg-light border-0"
                          placeholderText="Select Appointment Date (mm/dd/yyyy)"
                          dateFormat="MM/dd/yyyy"
                          required
                          peekNextMonth
                          showMonthDropdown
                          showYearDropdown
                          dropdownMode="select"
                          minDate={new Date()}
                        />
                      </div>
                      <div className="col-12">
                        <TimePicker
                          className="form-control bg-light border-0"
                          onChange={(time) =>
                            setFormData((prevFormData) => ({
                              ...prevFormData,
                              ATime: time,
                            }))
                          }
                          value={formData.ATime}
                          required
                          format="HH:mm"
                          clearIcon={null} // To hide the clear icon
                          style={{ fontSize: "16px", width: "100%" }} // Adjust the font size and width as needed
                        />
                      </div>
                      <div className="col-12">
                      <select
  className="form-select bg-light border-0"
  style={{ height: 55 }}
  name="ADhId"
  required
  value={formData.ADhId}
  onChange={handleInputChangeA}
>
  <option selected>Select Hospital</option>
  {hospitals.map((hospital) => (
    <option key={hospital.hId} value={hospital.hId}>
      {hospital.hName}
    </option>
  ))}
</select>

                      </div>
                      <div className="col-12">
                      <select
  className="form-select bg-light border-0"
  style={{ height: 55 }}
  name="ADId"
  required
  value={formData.ADId}
  onChange={handleInputChangeA}
>
  <option selected>Select Doctor</option>
  {doctorsA.map((doctor) => (
    <option key={doctor.dId} value={doctor.dId}>
      {doctor.dName}
    </option>
  ))}
</select>
                      </div>
                      <div className="col-12">
                        <input
                          type="text"
                          className="form-control bg-light border-0"
                          placeholder="Select Appointment Type"
                          style={{ height: 55 }}
                          name="AType"
                          required
                          value={formData.AType}
                          onChange={handleInputChangeA}
                        />
                      </div>
                      <div className="col-12">
                        <input
                          type="tel"
                          className="form-control bg-light border-0"
                          placeholder="Contact No."
                          style={{ height: 55 }}
                          name="AMobile"
                          required
                          value={formData.AMobile}
                          onChange={handleInputChangeA}
                        />
                      </div>
                      <div className="col-12">
                        <input
                          type="email"
                          className="form-control bg-light border-0"
                          placeholder="Your Email"
                          style={{ height: 55 }}
                          name="AEmail"
                          required
                          value={formData.AEmail}
                          onChange={handleInputChangeA}
                        />
                      </div>
                      <div className="col-12">
                        <textarea
                          className="form-control bg-light border-0"
                          placeholder="Appointment Reason"
                          style={{ height: 100 }}
                          name="AReason"
                          required
                          value={formData.AReason}
                          onChange={handleInputChangeA}
                        ></textarea>
                      </div>
                      <div className="col-12">
                        <button
                          className="btn btn-primary w-100 py-3"
                          type="submit"
                        >
                          Make An Appointment
                        </button>
                      </div>
                    </div>
                  </form>
                </div>
              </div>
            </div>
          </div>
        </div>

        <a
          href="#"
          className="btn btn-lg btn-primary btn-lg-square back-to-top"
        >
          <i className="bi bi-arrow-up" />
        </a>
      </div>
    </div>
  );
}

export default Home;
